      source: '大河报（腾讯新闻）',
      url: 'https://new.qq.com/rain/a/20260804A0BE9W00?refer=cp_1009',
      kicker: '法治 · 社会学',
      gist: '无锡朱女士发现丈夫伪造结婚证，与第三者在上海中山医院做试管婴儿并培育出受精卵；她向医院申请销毁这枚婚外胚胎遭拒，遂向上海市卫健委反映。卫健委答复称医院已按规定查验证件、尚无违法证据，目前已停止相关服务、胚胎封存，但“无相应职责”建议通过司法途径主张；7月30日该案在徐汇法院一审开庭未宣判，丈夫8月4日称愿配合销毁，朱女士申请刑事立案监督。',
