      essayQuote: '一枚婚外胚胎，把一段二十年婚姻撕开了一道最私密的口子。卫健委“无相应职责、建议走司法”的答复，看似冷淡，却点出一个真问题：胚胎的去留涉及人格权与辅助生殖伦理，必须由法院在权利框架内裁断，而非某个部门一锤定音。当家庭边界崩塌，最后兜底的，往往是法律对“人”的重新界定。',
