          lens:'情绪与动机', lensId:'psy_emotion',
          body:'<b>情绪与动机</b>研究告诉我们，人在群体性、即时反馈、竞争氛围里很容易被情绪劫持，做出冷静时不会做的冲动消费。团播的PK赛制正是把"同侪压力+胜负心+即时奖励"叠在一起，专挑情绪最上头的一刻下手——被整治，正是因为这种设计在系统性地放大人的脆弱面。',
