          body:'<b>科技社会学</b>关心技术如何重塑"什么是人、什么算劳动"。当生成式AI能稳定产出有辨识度的虚拟形象并积累粉丝，它就把"人格"变成了可批量制造、零罢工、永不塌房的生产资料——技术不是在替代某个岗位，而是在重新定义"偶像"这件商品的来源。',
