        {t:'后果', x:'2018年项目完工，总投资2230万余元；因运营入不敷出，灯会被拆、水秀闲置，国家利益受损，群众反映强烈。'},
        {t:'查处', x:'陈华今年1月被查、6月被"双开"、7月被逮捕，通报指其搞劳民伤财的"形象工程""政绩工程"。'}
