          lens:'新制度主义', lensId:'institutionalism',
          body:'<b>新制度主义</b>指出，人的行为深受"什么被奖励"的制度信号引导。当晋升考核看重短期可见的"项目亮点"而非长期民生，一些干部就会把公共资金投向能快速出形象的工程——问题不全在个人操守，而在考核指挥棒把"政绩"定义偏了。',
          aha:'烂尾的不是项目，是被错位的考核指挥棒。'
