          naive:'以为预警发完就结束了。',
          lens:'技术', lensId:'technology',
          body:'<b>技术</b>社会学角度看，这套系统把国家级的权威预警信号，通过微信的高并发推送“下沉”到每个人手机，又用“震感上报”把分散在千万用户处的真实感受回收成数据。技术在这里不只是发通知，而是织起一张“官方+公众”的协同网络，补足专业台站覆盖不到的盲区。',
          aha:'最好的预警系统，不是只说话的广播，而是能让每个人既听、也能回话的网络。'
