      title: '央视财经曝光水光针医美乱象：无资质机构违规注射、走私“三无”针剂横行',
      source: '央视财经',
      url: 'https://m.chinanews.com/wap/detail/cht/zw/10458642.shtml',
      kicker: '健康 · 健康 / 社会学',
      gist: '8月3日，央视财经《财经调查》揭露水光针市场乱象：部分正规医美机构违规将“械二类”产品用于注射，无资质美容店公然提供代打，化妆品批发市场走私“三无”针剂、违禁麻贴肆意流通。',
      major: true,
      platforms: ['微博热搜', '百度热搜', '今日头条', '抖音'],
      thread: [
        {t:'调查曝光', x:'《财经调查》记者亲测发现，广东韩妃整形违规使用“丝丽516动能素”（械二）注射；姬妍兮诊所违规注射未获械三批号产品；深圳“遇见美”生活美容店无资质走私代打。'},
        {t:'乱象链条', x:'明通化妆品批发市场公然售卖无中文标识的外版水光针与违禁麻贴，小红书竟成药商、代打人员接单平台，无名工作室无门脸、无资质、无底线。'},
        {t:'监管跟进', x:'广东省疾控局随后组织对涉事机构立案调查；水光针属第三类医疗器械，须由专业医务人员在医疗机构操作。'}
      ],
      interpretations: [
        {
          q:'为什么“打个水光针”会这么危险？',
          naive:'以为医美就是普通美容，随便哪儿都能做。',
          lens:'健康', lensId:'health',
          body:'<b>健康</b>社会学视角下，水光针属于侵入式医疗行为，必须是获批的第三类医疗器械、由专业医务人员操作。违规注射“械二”产品、使用含违禁麻药成分的敷料、甚至走私“三无”针剂，带来的不是“变美”而是感染、栓塞、器官损伤等真实健康风险，轻则毁容、重则危及生命。',
          aha:'“轻医美”三个字再轻，也轻不过它本来的医疗属性。'
        },
        {
          q:'为什么黑医美总在暑期“旺季”冒头？',
          naive:'以为只是个别商家坏。',
          lens:'越轨', lensId:'deviance',
          body:'<b>越轨</b>社会学提示，当监管缝隙、暴利诱惑与消费者“贪便宜、怕麻烦”的心态叠加，就会出现系统性的违规生态：机构混淆“械字号”概念、平台默许代打接单、批发市场公然售假，每一环都在试探底线。黑医美不是单点作恶，而是一条靠“信息差”牟利的灰色产业链。',
          aha:'每一次“低价变美”的侥幸，都是在给那条灰色链条续命。'
        }
      ],
      theories: [
        {id:'health', label:'健康'},
        {id:'deviance', label:'越轨'}
      ],
      essayTopics: [{"id":"fairness","label":"公平正义"}, {"id":"trust","label":"信任"}],
      review: {strength:'strong', disciplines:['soc','psy']}
